#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    std::vector<double> triangleAngles(double a, double b, double c) {
        std::vector<double> sides = {a, b, c};
        std::sort(sides.begin(), sides.end());
        if (sides[0] + sides[1] <= sides[2]) return {};

        auto getAngle = [](double x, double y, double z) {
            double cosVal = (y * y + z * z - x * x) / (2 * y * z);
            cosVal = std::max(-1.0, std::min(1.0, cosVal));
            return std::acos(cosVal) * 180.0 / M_PI;
        };

        std::vector<double> angles = {getAngle(a, b, c), getAngle(b, a, c), getAngle(c, a, b)};
        for (double& ang : angles) ang = std::round(ang * 100.0) / 100.0;
        std::sort(angles.begin(), angles.end());
        return angles;
    }
};

import java.util.*;

class Solution {
    public double[] triangleAngles(double a, double b, double c) {
        double[] sides = {a, b, c};
        Arrays.sort(sides);
        if (sides[0] + sides[1] <= sides[2]) return new double[]{};

        double[] angles = {getAngle(a, b, c), getAngle(b, a, c), getAngle(c, a, b)};
        for (int i = 0; i < 3; i++) angles[i] = Math.round(angles[i] * 100.0) / 100.0;
        Arrays.sort(angles);
        return angles;
    }

    private double getAngle(double x, double y, double z) {
        double cosVal = (y * y + z * z - x * x) / (2 * y * z);
        cosVal = Math.max(-1.0, Math.min(1.0, cosVal));
        return Math.toDegrees(Math.acos(cosVal));
    }
}

function triangleAngles(a, b, c) {
    const sides = [a, b, c].sort((x, y) => x - y);
    if (sides[0] + sides[1] <= sides[2]) return [];

    const getAngle = (x, y, z) => {
        let cosVal = (y * y + z * z - x * x) / (2 * y * z);
        cosVal = Math.max(-1.0, Math.min(1.0, cosVal));
        return (Math.acos(cosVal) * 180) / Math.PI;
    };

    const angles = [getAngle(a, b, c), getAngle(b, a, c), getAngle(c, a, b)];
    const rounded = angles.map(v => Math.round(v * 100) / 100);
    return rounded.sort((x, y) => x - y);
}
